/* ============================================================
   أطياب الجاسم (React) — الهيدر الأساسي

   · الشعار (يعود للصفحة الرئيسية) + أزرار التنقّل + أدوات الحساب.
   · أزرار التنقّل تستدعي الصفحات من ملفها (constants/pages registry):
     كل زر يحمل `data-page`، ووجهته من ATYAB_PAGES في ملف البيانات —
     فلا يوجد رابط مكتوب يدوياً مرتين.
   · الوضع الضيّق (≤1220px): يبقى الشعار أقصى اليمين و«الشطيرة» أقصى
     اليسار، وبينهما شريط أدوات مصغَّر: للعميل المسجَّل (العربة · البحث ·
     تبديل الوضع الليلي/النهاري)، وللزائر زر «سجل الآن» بدلها.
   · الهيدر يُضيف .scrolled عند التمرير، ويضبط --header-h (يستعمله
     شريط التصنيفات الثابت وكل ما يلتصق تحت الهيدر).
   ============================================================ */

import { useCallback, useEffect, useRef, useState, useSyncExternalStore } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { PATHS, pathForPage } from "../../routes.js";
import { ATYAB_PAGES } from "../../data/appConfig.js";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { uiActions } from "../../redux/slices/uiSlice.js";
import { NAV_ITEMS } from "../../constants/navItems.js";
import { t } from "../../i18n.js";
import { selectCartTotals } from "../../redux/selectors.js";
import { Icon } from "../Source/Icons.jsx";
import SmallHeader from "./SmallHeader.jsx";

/* وجهة أي زر في الهيدر — تُقرأ من ATYAB_PAGES وتُحوَّل إلى مسار راوتر */
function target(key) {
  return pathForPage(key, ATYAB_PAGES);
}

/* ------------------------------------------------------------
   خطّاف مقاس الشاشة — بـuseSyncExternalStore
   (قراءة متزامنة من matchMedia بلا setState داخل effect، فلا
    إعادة رسم متتالية ولا خطأ react-hooks/set-state-in-effect)
   ------------------------------------------------------------ */
function subscribeMedia(query, onChange) {
  if (typeof window === "undefined" || !window.matchMedia) return function () {};
  const mq = window.matchMedia(query);
  if (mq.addEventListener) mq.addEventListener("change", onChange);
  else if (mq.addListener) mq.addListener(onChange);
  return function () {
    if (mq.removeEventListener) mq.removeEventListener("change", onChange);
    else if (mq.removeListener) mq.removeListener(onChange);
  };
}

function readMedia(query) {
  return typeof window !== "undefined" && window.matchMedia ? window.matchMedia(query).matches : false;
}

function serverSnapshot() {
  return false;
}

function useMediaQuery(query) {
  const subscribe = useCallback(
    function (onChange) {
      return subscribeMedia(query, onChange);
    },
    [query]
  );
  const getSnapshot = useCallback(
    function () {
      return readMedia(query);
    },
    [query]
  );
  return useSyncExternalStore(subscribe, getSnapshot, serverSnapshot);
}

export default function MainHeader() {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const location = useLocation();
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const navOpen = useAppSelector(function (s) {
    return s.ui.mobileNavOpen;
  });
  /* ★ الشارة من الفاتورة المحسوبة (منتجات موجودة فعلاً في الكتالوج)،
     لا من الصفوف الخام — وإلا ظهر رقم على الأيقونة والعربة فارغة
     حين تفشل واجهة المنتجات أو تتغيّر الأصناف */
  const cartCount = useAppSelector(function (s) {
    return selectCartTotals(s).count;
  });
  /* ★ الصدق أولاً: «حسابي» تُعرض فقط مع customerId حقيقي من الخادم —
     بريد محلي بلا ربط (توكن ميت/خادم غير reachable) يُعرض «تسجيل الدخول»،
     وإلا كذبت الأيقونة على العميل وهو فعلياً ضيف عند كل المزايا. */
  const session = useAppSelector(function (s) {
    return s.user.auth && s.user.auth.customerId ? s.user.session : null;
  });
  const catalogActive = useAppSelector(function (s) {
    return s.catalog.active;
  });

  const headerRef = useRef(null);
  const [scrolled, setScrolled] = useState(false);
  const [progress, setProgress] = useState(0);
  const [showTop, setShowTop] = useState(false);
  const narrow = useMediaQuery("(max-width: 1220px)");

  const isEn = language === "en";

  /* ارتفاع الهيدر الحقيقي → --header-h (شريط التصنيفات الثابت يعتمد عليه) */
  const syncHeaderHeight = useCallback(function () {
    const el = headerRef.current;
    if (!el) return;
    const h = Math.round(el.offsetHeight);
    if (h > 0) document.documentElement.style.setProperty("--header-h", h + "px");
  }, []);

  useEffect(
    function () {
      function onScroll() {
        const y = window.scrollY || document.documentElement.scrollTop || 0;
        setScrolled(y > 12);
        setShowTop(y > 620);
        const max = document.documentElement.scrollHeight - window.innerHeight;
        setProgress(max > 0 ? Math.min(1, Math.max(0, y / max)) : 0);
      }
      window.addEventListener("scroll", onScroll, { passive: true });
      window.addEventListener("resize", onScroll);
      onScroll();
      return function () {
        window.removeEventListener("scroll", onScroll);
        window.removeEventListener("resize", onScroll);
      };
    },
    []
  );

  useEffect(
    function () {
      syncHeaderHeight();
      const timers = [0, 400, 1200].map(function (ms) {
        return window.setTimeout(syncHeaderHeight, ms);
      });
      window.addEventListener("resize", syncHeaderHeight);
      window.addEventListener("orientationchange", syncHeaderHeight);
      if (document.fonts && document.fonts.ready) document.fonts.ready.then(syncHeaderHeight).catch(function () {});
      let ro = null;
      if (window.ResizeObserver && headerRef.current) {
        ro = new ResizeObserver(syncHeaderHeight);
        ro.observe(headerRef.current);
      }
      return function () {
        timers.forEach(function (id) {
          window.clearTimeout(id);
        });
        window.removeEventListener("resize", syncHeaderHeight);
        window.removeEventListener("orientationchange", syncHeaderHeight);
        if (ro) ro.disconnect();
      };
    },
    [syncHeaderHeight]
  );

  /* إغلاق قائمة الجوال بالنقر على الخلفية أو بمفتاح Escape */
  useEffect(
    function () {
      if (!navOpen) return undefined;
      function onKey(e) {
        if (e.key === "Escape") dispatch(uiActions.setMobileNav(false));
      }
      document.addEventListener("keydown", onKey);
      return function () {
        document.removeEventListener("keydown", onKey);
      };
    },
    [navOpen, dispatch]
  );

  /* الزر النشط — يُشتق من مسار الراوتر الحالي */
  function activeKeyOf(pathname) {
    if (pathname === PATHS.perfumes) return "perfumes";
    if (pathname === PATHS.incense) return "incense";
    if (pathname === PATHS.offers) return "offers";
    if (pathname === PATHS.contact) return "contact";
    if (pathname === PATHS.shipping) return "shipping";
    if (pathname === PATHS.branches) return "branches";
    if (pathname === PATHS.profile || pathname === PATHS.wishlist) return "profile";
    if (pathname.indexOf(PATHS.product + "/") === 0) {
      return catalogActive === "incense" ? "incense" : "perfumes";
    }
    return "";
  }

  const active = activeKeyOf(location.pathname);

  /* أدوات الحساب/البحث/العربة — تُبنى مرة واحدة ثم تُركَّب حسب المقاس */

  const searchBtn = (
    <button
      className="tool-btn"
      id="searchBtn"
      type="button"
      aria-label={isEn ? "Search" : "البحث"}
      title={isEn ? "Search" : "البحث"}
      onClick={function () {
        navigate(target("search"));
      }}
    >
      <Icon name="search" strokeWidth={1.8} />
      <span className="tool-label">{isEn ? "Search" : "البحث"}</span>
    </button>
  );

  const cartBtn = (
    <button
      className="tool-btn"
      id="cartBtn"
      type="button"
      aria-label={(isEn ? "Shopping cart" : "عربة التسوق") + (cartCount > 0 ? " — " + cartCount : "")}
      title={isEn ? "Shopping cart" : "عربة التسوق"}
      onClick={function () {
        navigate(target("cart"));
      }}
    >
      <Icon name="cart" />
      <span className="tool-badge" id="cartCount" hidden={cartCount <= 0}>
        {cartCount > 99 ? "99+" : cartCount}
      </span>
      <span className="tool-label">{isEn ? "Shopping cart" : "عربة التسوق"}</span>
    </button>
  );

  const themeBtn = (
    <button
      className="theme-toggle"
      id="themeToggle"
      type="button"
      aria-label={isEn ? "Dark / light mode" : "تبديل الوضع الليلي والنهاري"}
      title={isEn ? "Dark / light mode" : "الوضع الليلي / النهاري"}
      onClick={function () {
        dispatch(uiActions.toggleTheme());
      }}
    >
      <Icon name="moon" className="ico ico-moon" />
      <Icon name="sun" className="ico ico-sun" />
    </button>
  );

  /* ★ الدخول الطوعي أثناء التصفح (السيناريو الثالث): نمرّر الصفحة الحالية
     كـ returnTo — بعد الدخول يعود العميل لنفس المنتج لا للمنتجات عامة. */
  const loginFrom = location.pathname + (location.search || "");
  const registerBtn = (
    <Link
      className={"btn-getstarted" + (session ? " is-account" : "")}
      id="registerBtn"
      to={session ? target("profile") : target("login")}
      state={session ? undefined : { from: loginFrom }}
      data-page={session ? "profile" : "login"}
    >
      {session ? <Icon name="user" /> : null}
      <span>{session ? (isEn ? "My account" : "حسابي") : isEn ? "Log in" : "تسجيل الدخول"}</span>
    </Link>
  );

  /* الوضع الواسع: كل الأدوات في صفّ واحد يسار الهيدر */
  function tools() {
    return (
      <div className="header-tools">
        {searchBtn}
        {cartBtn}
        {themeBtn}
        {registerBtn}
      </div>
    );
  }

  /* ★ شريط الهاتف: بين الشعار (أقصى اليمين) و«الشطيرة» (أقصى اليسار).
     مسجَّل ← العربة · البحث · تبديل الوضع.  زائر ← زر «سجل الآن» فقط. */
  function barTools() {
    if (!session) {
      return <div className="header-tools header-tools--guest">{registerBtn}</div>;
    }
    return (
      <div className="header-tools header-tools--bar">
        {cartBtn}
        {searchBtn}
        {themeBtn}
      </div>
    );
  }

  return (
    <>
      <div className="scroll-progress" id="scrollProgress" style={{ transform: "scaleX(" + progress + ")" }} />

      <header ref={headerRef} id="header" className={"header" + (scrolled ? " scrolled" : "")}>
        <SmallHeader />

        <div className="container header-inner">
          <Link to={PATHS.home} className="logo" data-page="home" aria-label={isEn ? "Atyab Al-Jasem — home page" : "أطياب الجاسم — الصفحة الرئيسية"}>
            <span className="logo-mark logo-mark--emblem" aria-hidden="true">
              <img
                src={(process.env.PUBLIC_URL || "") + "/atyab-emblem.png"}
                alt=""
                onError={function (e) { try { e.currentTarget.style.display = "none"; } catch (err) {} }}
              />
            </span>
            <span className="sitename">
              أطياب الجاسم<small>ATYAB AL-JASEM</small>
            </span>
          </Link>

          {narrow ? barTools() : null}

          <nav id="navmenu" className="navmenu">
            <ul
              onClick={function (e) {
                /* النقر على الخلفية (لا على رابط) يُغلق القائمة */
                if (e.target === e.currentTarget && navOpen) dispatch(uiActions.setMobileNav(false));
              }}
            >
              <li className="nav-offers-li">
                <Link to={target("offers")} className={"nav-offers" + (active === "offers" ? " active" : "")} data-page="offers">
                  <Icon name="tag" strokeWidth={1.8} />
                  <span>{isEn ? t("en", "nav.offers", "العروض") : "العروض"}</span>
                  <i className="nav-offers-spark" aria-hidden="true" />
                </Link>
              </li>

              {NAV_ITEMS.map(function (item) {
                return (
                  <li key={item.page}>
                    <Link
                      to={target(item.page)}
                      data-page={item.page}
                      className={active === item.page ? "active" : ""}
                      aria-current={active === item.page ? "page" : undefined}
                    >
                      {isEn ? t("en", item.i18n, item.label) : item.label}
                    </Link>
                  </li>
                );
              })}

              {/* ★ الوضع الضيّق: «حسابي» يبقى في القائمة حتى لا يفقده العميل
                 المسجَّل (شريط الهاتف مخصَّص للعربة/البحث/الوضع فقط). */}
              {narrow ? (
                <li>
                  <Link
                    to={target("profile")}
                    data-page="profile"
                    className={active === "profile" ? "active" : ""}
                    aria-current={active === "profile" ? "page" : undefined}
                  >
                    {isEn ? "My account" : "حسابي"}
                  </Link>
                </li>
              ) : null}
            </ul>

            <button
              className="mobile-nav-toggle"
              id="navToggle"
              type="button"
              aria-label={isEn ? "Menu" : "القائمة"}
              aria-expanded={navOpen ? "true" : "false"}
              onClick={function () {
                dispatch(uiActions.setMobileNav(!navOpen));
              }}
            >
              <Icon name="menu" strokeWidth={1.9} />
            </button>
          </nav>

          {narrow ? null : tools()}
        </div>
      </header>

      {showTop ? (
        <button
          type="button"
          id="scrollTop"
          className="scroll-top active"
          aria-label={isEn ? "Back to top" : "أعلى الصفحة"}
          onClick={function () {
            try {
              var el = document.getElementById("root");
              while (el) {
                try {
                  if (el.scrollTop > 0) el.scrollTop = 0;
                } catch (e) {}
                el = el.parentElement;
              }
              if (document.documentElement) document.documentElement.scrollTop = 0;
              if (document.body) document.body.scrollTop = 0;
              window.scrollTo({ top: 0, behavior: "smooth" });
            } catch (e) {
              try {
                window.scrollTo(0, 0);
              } catch (e2) {}
            }
          }}
        >
          <Icon name="up" strokeWidth={2.2} />
        </button>
      ) : null}
    </>
  );
}
