function digits(s) {
  return String(s == null ? "" : s).replace(/\D/g, "");
}

async function readJson(res) {
  const text = await res.text().catch(function () { return ""; });
  if (!text) return null;
  try { return JSON.parse(text); } catch (e) { return null; }
}

function serverMessage(payload, fallback) {
  if (!payload) return fallback;
  if (typeof payload === "string") return payload;
  const errs = payload.errors;
  if (errs && typeof errs === "object") {
    const parts = [];
    Object.keys(errs).forEach(function (k) {
      const v = errs[k];
      if (Array.isArray(v)) parts.push(k + ": " + v.join(" "));
      else if (v) parts.push(k + ": " + v);
    });
    if (parts.length) return parts.join(" | ");
  }
  /* ★ مغلّف الخطأ الموحّد (§0): detail العربية أولاً */
  return payload.detail || payload.message || payload.title || payload.error || fallback;
}

function throwForStatus(res, payload) {
  let msg = serverMessage(payload, "استجابة الخادم: " + res.status);
  /* ★ 409 على الملف = الهاتف مستخدم في حساب آخر (§5) — رسالة تمييز
     صريحة بدل الجملة التقنية، مع إبقاء تفصيل الخادم */
  if (res.status === 409 && /phone|هاتف|used|مستخدم|مكرر|exists|taken/i.test(msg)) {
    msg = "هذا الهاتف مستخدم في حساب آخر — غيّر الرقم، أو سجّل الدخول بذلك الحساب. (" + msg + ")";
  }
  try { atyabLog("customers HTTP " + res.status, JSON.stringify(payload)); } catch (e) {}
  const err = apiError(msg, res.status);
  err.response = { status: res.status, data: payload };
  throw err;
}

export function normalizeLocations(payload) {
  if (!payload) return [];
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload.data)) return payload.data;
  if (Array.isArray(payload.items)) return payload.items;
  if (Array.isArray(payload.locations)) return payload.locations;
  if (payload.locationId != null) return [payload];
  return [];
}

export async function getCustomer(id) {
  const res = await authFetch(ENDPOINTS.customerDetails(id), { method: "GET" });
  const payload = await readJson(res);
  if (!res.ok) throwForStatus(res, payload);
  return payload;
}

export async function updateCustomer(id, body) {
  const res = await authFetch(ENDPOINTS.customerDetails(id), {
    method: "PUT",
    body: { firstName: body.firstName, lastName: body.lastName, phoneNumber: body.phoneNumber }
  });
  const payload = await readJson(res);
  if (!res.ok) throwForStatus(res, payload);
  atyabLog("customer UPDATE ok");
  return payload;
}

