const TEMP_COUNTRY_IDS = { AE: 1, SA: 2, KW: 3, QA: 4, BH: 5, OM: 6 };
const TEMP_CITY_IDS = {};

export function resolveCountryId(regionKey) {
  const k = String(regionKey || "AE").toUpperCase();
  return TEMP_COUNTRY_IDS[k] || 1;
}

export function resolveCityId(cityName, regionKey) {
  const name = String(cityName || "").trim();
  if (TEMP_CITY_IDS[name] != null) return TEMP_CITY_IDS[name];
  let h = 0;
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) % 900 + 10;
  return h || 1;
}

export function countryKeyOfId(id) {
  const n = Number(id);
  const keys = Object.keys(TEMP_COUNTRY_IDS);
  for (let i = 0; i < keys.length; i++) {
    if (TEMP_COUNTRY_IDS[keys[i]] === n) return keys[i];
  }
  return "AE";
}

/* ---------- اكتشاف countryId/cityId الحقيقية من الخادم (مع تخزين مؤقت) ---------- */

const ID_CACHE_KEY = "atyab:location-ids";
const NAME_KEYS = ["name", "nameAr", "arabicName", "label", "labelAr", "title", "titleAr", "cityName", "countryName", "nameEn", "englishName", "labelEn"];

function readIdCache() {
  try {
    const raw = window.localStorage.getItem(ID_CACHE_KEY);
    const o = raw ? JSON.parse(raw) : null;
    return o && typeof o === "object" ? o : {};
  } catch (e) { return {}; }
}

function writeIdCache(c) {
  try { window.localStorage.setItem(ID_CACHE_KEY, JSON.stringify(c)); } catch (e) {}
}

function normName(s) {
  return String(s == null ? "" : s).trim().toLowerCase().replace(/\s+/g, " ");
}

export function numId(o, keys) {
  for (let i = 0; i < keys.length; i++) {
    const v = o[keys[i]];
    if (v != null && v !== "" && !isNaN(Number(v))) return Number(v);
  }
  return null;
}

export function matchItem(list, needles) {
  const want = needles.map(normName).filter(Boolean);
  if (!want.length) return null;
  for (let i = 0; i < list.length; i++) {
    const o = list[i] || {};
    const fields = [];
    NAME_KEYS.forEach(function (k) { if (o[k] != null) fields.push(o[k]); });
    Object.keys(o).forEach(function (k) {
      if (NAME_KEYS.indexOf(k) === -1 && typeof o[k] === "string") fields.push(o[k]);
    });
    for (let j = 0; j < fields.length; j++) {
      if (want.indexOf(normName(fields[j])) !== -1) return o;
    }
  }
  return null;
}

async function tryLookup(path) {
  try {
    const res = await authFetch(path, { method: "GET" });
    if (!res.ok) return null;
    const payload = await readJson(res);
    const list = normalizeLocations(payload);
    if (list.length) return list;
    if (Array.isArray(payload) || (payload && typeof payload === "object")) {
      const arr = Array.isArray(payload) ? payload : (payload.data || payload.items || payload.countries || payload.cities || null);
      if (Array.isArray(arr) && arr.length) return arr;
    }
    return null;
  } catch (e) { return null; }
}

const COUNTRY_ALIAS = {
  AE: ["UAE"], SA: ["Saudi Arabia", "KSA"], KW: ["Kuwait"],
  QA: ["Qatar"], BH: ["Bahrain"], OM: ["Oman"], US: ["USA", "United States"]
};

export function findCountryByRegion(countries, regionKey) {
  const rk = String(regionKey || "AE").toUpperCase();
  const list = Array.isArray(countries) ? countries : [];
  if (!list.length) return null;
  const c = countryByKey(rk) || {};
  return matchItem(list, [rk, c.label, c.labelEn, c.short, c.shortEn].concat(COUNTRY_ALIAS[rk] || []));
}

export function countryIdOfRow(o) {
  return numId(o || {}, ["countryId", "CountryId", "id", "Id"]);
}

export function cityIdOfRow(o) {
  return numId(o || {}, ["cityId", "CityId", "id", "Id"]);
}

/* قوائم الدول/المدن الحيّة — البيانات من الخادم دائماً (لا نُخزّنها في الكود).
   ★ عقد الباك-اند (مؤكد): لا يوجد /api/cities إطلاقاً.
   الصحيح: GET /api/countries ثم GET /api/countries/{countryId}/cities لكل دولة.
   نوسم كل مدينة بـ countryId عند الدمج لأن geoSlice يصفّي بها. */
export async function fetchGeoLists() {
  const countries = (await tryLookup("/api/countries")) || [];
  const all = [];
  for (let i = 0; i < countries.length; i++) {
    const cid = countryIdOfRow(countries[i]);
    if (cid == null) continue;
    const list = await tryLookup("/api/countries/" + cid + "/cities");
    if (!list) continue;
    list.forEach(function (o) {
      if (!o || typeof o !== "object") return;
      if (o.countryId == null && o.CountryId == null) {
        const copy = Object.assign({}, o);
        copy.countryId = cid;
        all.push(copy);
      } else {
        all.push(o);
      }
    });
  }
  return { countries: countries, cities: all };
}

export async function ensureLocationIds(regionKey, cityName) {
  const rk = String(regionKey || "AE").toUpperCase();
  const cn = String(cityName || "").trim();
  const cache = readIdCache();
  const ck = rk + "|" + cn;
  if (cache[ck]) return { countryId: cache[ck].countryId, cityId: cache[ck].cityId, source: "cache" };
  let countryId = null;
  let cityId = null;
  const countries = await tryLookup("/api/countries");
  if (countries) {
    const hit = findCountryByRegion(countries, rk);
    if (hit) countryId = countryIdOfRow(hit);
  }
  const cityPaths = [];
  if (countryId != null) {
    /* ★ المسار الوحيد الصحيح — لا /api/cities إطلاقاً */
    cityPaths.push("/api/countries/" + countryId + "/cities");
  } else if (countries) {
    /* ★ بلا دولة معروفة: جرّب مدن كل الدول بدل مسار عام غير موجود */
    for (let ci = 0; ci < countries.length; ci++) {
      const cid = countryIdOfRow(countries[ci]);
      if (cid != null) cityPaths.push("/api/countries/" + cid + "/cities");
    }
  }
  /* ★ الخادم يسمّي المدن بالإنجليزية (Sharjah) وقائمتنا بالعربية —
     نطابق بالاسمين معاً: قاموس الترجمة أولاً ثم جسر appConfig. */
  let cityNeedles = [cn];
  const viaMap = cityEn(cn);
  if (viaMap && cityNeedles.indexOf(viaMap) === -1) cityNeedles.push(viaMap);
  try {
    const cc = countryByKey(rk) || {};
    const found = ((cc && cc.cities) || []).filter(function (m) { return m.ar === cn; })[0];
    if (found && found.en && cityNeedles.indexOf(found.en) === -1) cityNeedles.push(found.en);
  } catch (e) {}
  let citiesSeen = false;
  for (let i = 0; i < cityPaths.length; i++) {
    const list = await tryLookup(cityPaths[i]);
    if (!list) continue;
    citiesSeen = true;
    let pool = list;
    if (countryId != null) {
      const same = list.filter(function (o) {
        const v = o.countryId != null ? o.countryId : o.CountryId;
        return v == null || Number(v) === Number(countryId);
      });
      if (same.length) pool = same;
    }
    const hit = matchItem(pool, cityNeedles);
    if (hit) {
      cityId = numId(hit, ["id", "Id", "cityId", "CityId"]);
      if (cityId != null) break;
    }
  }
  /* ★ القائمة وصلت لكن مدينتنا ليست فيها؟ لا نرسل رقماً وهمياً أبداً —
     نوقف العملية برسالة تذكر المتاح، بدل 400 مبهمة من الخادم. */
  if (cityId == null && citiesSeen) {
    const names = [];
    try {
      const all = countryId != null
        ? await tryLookup("/api/countries/" + countryId + "/cities")
        : null;
      (all || []).slice(0, 12).forEach(function (o) {
        const n = o.cityName || o.name || o.nameAr;
        if (n) names.push(n);
      });
    } catch (e) {}
    throw apiError(
      "المدينة «" + cn + "» غير متوفرة في الخادم" + (names.length ? " — المتاح: " + names.join("، ") : "") + ".",
      0,
      "ECITYUNKNOWN"
    );
  }
  if (countryId != null && cityId != null) {
    cache[ck] = { countryId: countryId, cityId: cityId };
    writeIdCache(cache);
    return { countryId: countryId, cityId: cityId, source: "api" };
  }
  return {
    countryId: countryId != null ? countryId : resolveCountryId(rk),
    cityId: cityId != null ? cityId : resolveCityId(cn, rk),
    source: "temp"
  };
}

function addressTypeOut(t) {
  const s = String(t || "home").toLowerCase();
  if (s === "work") return "Work";
  if (s === "other") return "Other";
  return "Home";
}

export function toLocationBody(form) {
  const f = form || {};
  const buildingText = String(f.building == null ? "" : f.building);
  const num = digits(buildingText);
  return {
    countryId: Number(f.countryId != null ? f.countryId : resolveCountryId(f.region)),
    cityId: Number(f.cityId != null ? f.cityId : resolveCityId(f.city, f.region)),
    street: String(f.street || ""),
    area: String(f.district || f.area || ""),
    zipCode: String(f.postal || f.zipCode || ""),
    buildingName: buildingText,
    buildingNumber: num || buildingText || "1",
    nearTo: String(f.landmark || f.nearTo || ""),
    addressType: addressTypeOut(f.type || f.addressType || f.propertyType),
    deliveryNote: String(f.notes || f.deliveryNote || ""),
    isDefault: f.isDefault == null ? true : !!f.isDefault
  };
}

export function fromLocation(loc) {
  const l = loc || {};
  return {
    locationId: l.locationId != null ? l.locationId : (l.id != null ? l.id : null),
    region: countryKeyOfId(l.countryId),
    countryId: l.countryId,
    cityId: l.cityId,
    city: cityAr(l.cityName || l.city || "") || "",
    district: l.area || "",
    street: l.street || "",
    building: l.buildingName || l.buildingNumber || "",
    postal: l.zipCode || "",
    landmark: l.nearTo || "",
    type: String(l.addressType || "home").toLowerCase() === "work" ? "work" : "home",
    propertyType: String(l.addressType || "").toLowerCase().indexOf("work") !== -1 ? "office" : "",
    notes: l.deliveryNote || "",
    isDefault: !!l.isDefault
  };
}
