/* ============================================================
   أطياب الجاسم (React) — شريحة العربة (cartSlice)

   مصدر واحد لحقيقة العربة: القطع، الكوبون، طريقة الدفع، رقم الفاتورة،
   والرسائل (تنبيه الفاتورة/الدفع + رسالة الكوبون) — كما في src/cart.js
   القديم حرفياً حتى لا تتغيّر تجربة العميل.

   الأسعار بالدرهم الإماراتي دائماً (محاسبة المالك)، والتحويل عند العرض فقط (selectors.js).
   الرسوم:  شحن ٢٥ د.إ — مجاني فوق ٣٠٠ — ضريبة ٥٪ مضمّنة في الأسعار.
   ============================================================ */

import { createSlice } from "@reduxjs/toolkit";
import { ATYAB_byId } from "../../data/products.js";
import { KEYS, readJSON, readRaw, writeJSON } from "../persist.js";
import { uiActions } from "./uiSlice.js";
import { authFetch } from "../../api/auth.js";
import { ENDPOINTS, atyabLog } from "../api.js";
import { unitPriceOf } from "../selectors.js";
import { isValidCouponFormat } from "../../validation.js";

/* ★ الثوابت من وحدة مستقلة (shopConstants) — لا استيراد دائري مع selectors.
   إعادة التصدير هنا حتى تبقى مسارات الاستيراد القديمة كما هي. */
import {
  FREE_SHIP_OVER,
  SHIP_FEE,
  VAT_RATE,
  MAX_PER_ITEM,
  COUPONS
} from "../shopConstants.js";
export {
  FREE_SHIP_OVER,
  SHIP_FEE,
  VAT_RATE,
  MAX_PER_ITEM,
  COUPONS
} from "../shopConstants.js";

/* طرق الدفع كما في صفحة العربة القديمة (قيمة فارغة = لم يُختر بعد)
   ★ en = الاسم بالإنجليزية، يُقرأ عبر payMethodLabel(key, lang) */
export const PAY_METHODS = [
  { key: "", label: "— اختر طريقة الدفع —", en: "— Choose a payment method —" },
  { key: "mada", label: "بطاقة مدى", en: "Mada card" },
  { key: "visa", label: "فيزا / ماستركارد", en: "Visa / Mastercard" },
  { key: "applepay", label: "Apple Pay", en: "Apple Pay" },
  { key: "stcpay", label: "STC Pay", en: "STC Pay" },
  { key: "transfer", label: "تحويل بنكي", en: "Bank transfer" },
  { key: "cod", label: "الدفع عند الاستلام", en: "Cash on delivery" }
];

/* اسم طريقة الدفع بلغة الواجهة */
export function payMethodLabel(key, lang) {
  let found = null;
  PAY_METHODS.forEach(function (m) {
    if (m.key === key) found = m;
  });
  if (!found) return "";
  return lang === "en" ? found.en || found.label : found.label;
}

/* ---------- أدوات ---------- */
/* ★ الحد الأقصى يُحسب في الـthunks (thunk/handlers فقط) ويُمرَّر ضمن
   الـpayload — ولا يُستدعى أبداً داخل الـreducers (قراءة الـstore
   أثناء الـreducer كسرٌ للنقاء وتُرجع حالة قديمة). */
export function maxQtyOf(id) {
  const p = ATYAB_byId ? ATYAB_byId(Number(id)) : null;
  const stock = p && typeof p.stock === "number" ? p.stock : MAX_PER_ITEM;
  return Math.max(1, Math.min(stock, MAX_PER_ITEM));
}

/* ★ حدّ الـpayload الصالح — وإلا سقف الأمان العام (لا قراءة store هنا) */
function payloadMax(payload) {
  const m = Math.round(Number(payload && payload.max));
  if (m > 0) return Math.min(m, MAX_PER_ITEM);
  return MAX_PER_ITEM;
}

function makeInvoiceNo() {
  const d = new Date();
  const two = function (n) {
    return (n < 10 ? "0" : "") + n;
  };
  return (
    "AY-" +
    d.getFullYear() +
    two(d.getMonth() + 1) +
    two(d.getDate()) +
    "-" +
    Math.floor(1000 + Math.random() * 9000)
  );
}

function readRows() {
  const arr = readJSON(KEYS.cart, []);
  if (!Array.isArray(arr)) return [];
  const out = [];
  arr.forEach(function (row) {
    const id = Number(row && row.id);
    if (!id) return;
    const qty = Math.max(1, Math.min(MAX_PER_ITEM, Math.round(Number(row.qty) || 1)));
    let at = -1;
    out.forEach(function (r, i) {
      if (r.id === id) at = i;
    });
    if (at === -1) out.push({ id: id, qty: qty });
    else out[at].qty = Math.min(MAX_PER_ITEM, out[at].qty + qty);
  });
  return out;
}

function readCoupon() {
  return String(readRaw(KEYS.coupon, "") || "").toUpperCase();
}

const slice = createSlice({
  name: "cart",
  initialState: {
    rows: readRows(),
    coupon: readCoupon(),
    invoiceNo: makeInvoiceNo(),
    paymentMethod: "",
    couponMsg: null, /* { tone: "ok" | "bad", text } */
    couponInfo: null, /* حُكم الخادم الأخير { code, discountType, discountValue, snapshotNet } */
    couponBusy: false, /* تحقّق جارٍ من الخادم */
    notice: null, /* { tone, where: "invoice" | "pay", title, text } */
    removedNotice: null, /* { name, nameEn, at } — منتج نُزع لنفاد مخزونه */
    /* ★ مزامنة السلة: الخادم لا يعرف هذا الحساب (404 على POST)؟
       غالباً جلسة قديمة بعد تصفير قاعدة البيانات — نعرض تلميح إعادة الدخول. */
    basketStale: false,
    /* ★ آخر سحب للمزامنة فشل (شبكة/خادم)؟ بانر إعادة المحاولة في العربة */
    syncError: false
  },
  reducers: {
    /* إضافة قطعة — الحد الأقصى يأتي في الـpayload من الـthunk
       (addItem) ولا قراءة خارجية هنا. */
    addToCart: function (state, action) {
      const id = Number(action.payload && action.payload.id);
      const qty = Math.max(1, Math.round(Number(action.payload && action.payload.qty) || 1));
      if (!id) return;
      const max = payloadMax(action.payload);
      let row = null;
      state.rows.forEach(function (r) {
        if (r.id === id) row = r;
      });
      if (!row) state.rows.push({ id: id, qty: Math.min(max, qty) });
      else {
        if (action.payload && action.payload.itemId != null && row.itemId == null) row.itemId = Number(action.payload.itemId);
        row.qty = Math.min(max, row.qty + qty);
      }
    },
    setQty: function (state, action) {
      const id = Number(action.payload && action.payload.id);
      const qty = Math.round(Number(action.payload && action.payload.qty) || 0);
      if (!id) return;
      const max = payloadMax(action.payload);
      if (qty <= 0) {
        state.rows = state.rows.filter(function (r) {
          return r.id !== id;
        });
        return;
      }
      state.rows.forEach(function (r) {
        if (r.id === id) r.qty = Math.min(max, qty);
      });
    },
    /* (−) عند الكمية ١ يحذف القطعة — نفس سلوك الموقع القديم */
    stepQty: function (state, action) {
      const id = Number(action.payload && action.payload.id);
      const delta = Math.round(Number(action.payload && action.payload.delta) || 0);
      if (!id) return;
      const max = payloadMax(action.payload);
      let row = null;
      state.rows.forEach(function (r) {
        if (r.id === id) row = r;
      });
      if (!row) return;
      const next = row.qty + delta;
      if (next <= 0) {
        state.rows = state.rows.filter(function (r) {
          return r.id !== id;
        });
        return;
      }
      row.qty = Math.min(max, next);
    },
    removeRow: function (state, action) {
      const id = Number(action.payload);
      state.rows = state.rows.filter(function (r) {
        return r.id !== id;
      });
    },
    clearCart: function (state) {
      state.rows = [];
      state.coupon = "";
      state.couponInfo = null;
      state.couponMsg = null;
      state.notice = null;
      state.removedNotice = null;
      state.invoiceNo = makeInvoiceNo();
    },
    regenerateInvoice: function (state) {
      state.invoiceNo = makeInvoiceNo();
    },
    removeCoupon: function (state) {
      state.coupon = "";
      state.couponInfo = null;
      state.couponMsg = { tone: "bad", text: "تمت إزالة الكوبون.", textEn: "The coupon was removed." };
    },
    couponCheckStarted: function (state) {
      state.couponBusy = true;
    },
    couponCheckFailed: function (state) {
      state.couponBusy = false;
    },
    /* حُكم الخادم يحلّ محلّ الحالة كلها (خانة واحدة = كوبون واحد).
       keep:true (عطل شبكة) = نُبقي الكوبون القديم ونعرض رسالة فقط. */
    couponChecked: function (state, action) {
      const p = action.payload || {};
      state.couponBusy = false;
      if (p.keep) {
        state.couponMsg = { tone: "bad", text: p.message || "", textEn: p.messageEn || p.message || "" };
        return;
      }
      if (p.valid) {
        state.coupon = p.code;
        /* ★ الوصف من النوع لا من الكود — الكود يُعرض قبله في CouponBox
           (label: p.code كان يكرر الكود: «ATYAB3754ATYAB3754»). */
        const cType = p.discountType === "fixed" ? "fixed" : p.discountType === "shipping" ? "shipping" : "percent";
        const cVal = Number(p.discountValue) || 0;
        COUPONS[p.code] = {
          label: cType === "fixed" ? "خصم مبلغ ثابت" : cType === "shipping" ? "شحن مجاني" : "خصم " + cVal + "%",
          labelEn: cType === "fixed" ? "Fixed discount" : cType === "shipping" ? "Free shipping" : cVal + "% discount",
          type: cType,
          value: cVal
        };
        state.couponInfo = {
          code: p.code,
          discountType: String(p.discountType || "percent"),
          discountValue: Number(p.discountValue) || 0,
          serverDiscount: p.serverDiscount != null ? Number(p.serverDiscount) : null,
          serverTotal: p.serverTotal != null ? Number(p.serverTotal) : null,
          freeShipping: !!p.freeShipping,
          reason: "",
          snapshotNet: Number(p.snapshotNet) || 0
        };
        state.couponMsg = { tone: "ok", text: p.message || "", textEn: p.messageEn || p.message || "" };
      } else {
        state.coupon = "";
        state.couponInfo = null;
        state.couponMsg = { tone: "bad", text: p.message || "", textEn: p.messageEn || p.message || "" };
      }
    },
    setPaymentMethod: function (state, action) {
      state.paymentMethod = String(action.payload || "");
      if (state.notice && state.notice.where === "pay") state.notice = null;
    },
    /* ★ استبدال كامل من سلة الخادم (بعد سحب + دمج) — ملاحظات الصفوف
       (serverNote) تُحمَل مع الصف نفسه فلا تضيع بالاستبدال */
    basketReplaced: function (state, action) {
      const list = Array.isArray(action.payload) ? action.payload : [];
      const notes = {};
      (state.rows || []).forEach(function (r) {
        if (r && r.serverNote) notes[Number(r.id)] = String(r.serverNote);
      });
      const out = [];
      list.forEach(function (r) {
        const id = Number(r && r.id);
        if (!id) return;
        const max = payloadMax(r);
        const qty = Math.max(1, Math.min(max, Math.round(Number(r.qty) || 1)));
        let at = -1;
        out.forEach(function (o, i) {
          if (o.id === id) at = i;
        });
        const itemId = r && r.itemId != null ? Number(r.itemId) : undefined;
        const note = notes[id] != null ? notes[id] : (r && r.serverNote != null ? String(r.serverNote) : null);
        if (at === -1) {
          const row = { id: id, qty: qty };
          if (itemId != null) row.itemId = itemId;
          if (note) row.serverNote = note;
          out.push(row);
        } else {
          out[at].qty = Math.min(max, out[at].qty + qty);
          if (out[at].itemId == null && itemId != null) out[at].itemId = itemId;
          if (out[at].serverNote == null && note) out[at].serverNote = note;
        }
      });
      state.rows = out;
    },
    /* ★ ربط صف محلي برقم سطر الخادم بعد POST ناجح (ويمسح ملاحظته) */
    basketItemLinked: function (state, action) {
      const id = Number(action.payload && action.payload.id);
      const itemId = action.payload && action.payload.itemId != null ? Number(action.payload.itemId) : null;
      if (!id || itemId == null) return;
      state.rows.forEach(function (r) {
        if (r.id === id && r.itemId == null) r.itemId = itemId;
        if (r.id === id) r.serverNote = null;
      });
    },
    /* ★ ملاحظة الخادم على صف (404 منتج/مخزون): تُعرض على البطاقة نفسها
       بدل سطر log صامت — null تمسحها. */
    basketRowNote: function (state, action) {
      const id = Number(action.payload && action.payload.id);
      const note = action.payload && action.payload.note != null ? String(action.payload.note) : null;
      if (!id) return;
      state.rows.forEach(function (r) {
        if (r.id === id) r.serverNote = note;
      });
    },
    setNotice: function (state, action) {
      state.notice = action.payload || null;
    },
    basketStaleSet: function (state, action) {
      state.basketStale = action.payload !== false;
    },
    /* ★ حالة المزامنة الظاهرة: فشل آخر سحب (تُمسح عند أول نجاح) */
    basketSyncSet: function (state, action) {
      state.syncError = action.payload !== false;
    },
    /* ★ منتج نُزع من العربة لنفاد مخزونه رسمياً (409 بمتاح 0):
       بانر أعلى العربة «تمت إزالة كذا — انقر للحجز» حتى يراها العميل */
    stockRemoved: function (state, action) {
      const p = action.payload || {};
      state.removedNotice = {
        name: String(p.name || ""),
        nameEn: String(p.nameEn || p.name || ""),
        at: Date.now()
      };
    },
    stockRemovedSeen: function (state) {
      state.removedNotice = null;
    }
  }
});

export const cartActions = slice.actions;
export const cartReducer = slice.reducer;

/* ------------------------------------------------------------
   ثَنَوِيّات (thunks) تُطلق الحدث + التنبيه معاً — حتى لا يُكرَّر
   منطق الرسائل في كل كومبوننت يستدعي العربة.
   ★ الضرائب/الإجمالي تُحسَب في selectors، وتمرير «المبلغ الجاهز»
     لهذه الدوال يحفظ اتجاهاً واحداً للاعتماديات (بلا حلقات).
   ------------------------------------------------------------ */
export function addItem(id, qty) {
  return function (dispatch, getState) {
    const product = ATYAB_byId(Number(id));
    if (!product) return;
    const lang = (getState && getState().ui.language) || "ar";
    /* ★ نفد المخزون (صفر/غير نشط)؟ لا دخول للعربة إطلاقاً — الحجز فقط.
       زر «احجز الآن» (واتساب) على البطاقة هو الطريق، لا الإضافة. */
    const stock = product && typeof product.stock === "number" ? product.stock : null;
    const dead = !product.inStock || product.isActive === false || (stock != null && stock <= 0);
    if (dead) {
      const nm = (lang === "en" && product.nameEn) || product.name;
      dispatch(
        uiActions.toastShown(
          lang === "en"
            ? "«" + nm + "» is out of stock — it can only be reserved via WhatsApp"
            : "«" + nm + "» نفدت الكمية — لا يُضاف للعربة، متاح للحجز عبر واتساب"
        )
      );
      return;
    }
    const want = Math.max(1, Math.round(Number(qty) || 1));
    const max = maxQtyOf(id);
    /* الكمية الفعلية قبل الإضافة — لنعرف هل تغيّر شيء فعلاً */
    let before = 0;
    (getState().cart.rows || []).forEach(function (r) {
      if (r.id === Number(id)) before = r.qty;
    });
    dispatch(cartActions.addToCart({ id: Number(id), qty: want, max: max }));
    let after = before;
    (getState().cart.rows || []).forEach(function (r) {
      if (r.id === Number(id)) after = r.qty;
    });
    if (after <= before) {
      dispatch(
        uiActions.toastShown(
          lang === "en"
            ? "Maximum available quantity for this item (" + max + " pieces)"
            : "أقصى كمية متاحة لهذا العطر (" + max + " قطع)"
        )
      );
      return;
    }
    const itemName = (lang === "en" && product.nameEn) || product.name;
    dispatch(uiActions.toastShown(lang === "en" ? "Added «" + itemName + "» to the cart" : "أُضيف «" + itemName + "» إلى العربة"));
    const cid = serverCustomerId(getState);
    if (cid) mirrorUpsert(cid, dispatch, getState, Number(id));
  };
}

/* رسالة «حُذف … من العربة» بلغة الواجهة */
function removedMsg(product, lang) {
  const name = product ? (lang === "en" && product.nameEn) || product.name : "";
  if (lang === "en") return name ? "Removed «" + name + "» from the cart" : "Removed from the cart";
  return name ? "حُذف «" + name + "» من العربة" : "تم الحذف من العربة";
}

export function stepItem(id, delta) {
  return function (dispatch, getState) {
    const lang = (getState().ui && getState().ui.language) || "ar";
    const cid = serverCustomerId(getState);
    let row = null;
    (getState().cart.rows || []).forEach(function (r) {
      if (r.id === Number(id)) row = r;
    });
    const product = ATYAB_byId(Number(id));
    const qty = row ? row.qty : 0;
    const goneItemId = row && row.itemId != null ? row.itemId : null;
    if (delta < 0 && qty <= 1) {
      dispatch(cartActions.removeRow(Number(id)));
      dispatch(uiActions.toastShown(removedMsg(product, lang)));
      if (cid) mirrorRemove(cid, goneItemId);
      return;
    }
    dispatch(cartActions.stepQty({ id: Number(id), delta: delta, max: maxQtyOf(Number(id)) }));
    let next = null;
    (getState().cart.rows || []).forEach(function (r) {
      if (r.id === Number(id)) next = r;
    });
    if (delta > 0 && next && next.qty === qty) {
      dispatch(uiActions.toastShown(lang === "en" ? "Maximum available quantity for this item" : "أقصى كمية متاحة لهذا المنتج"));
    }
    if (cid && next) mirrorUpsert(cid, dispatch, getState, Number(id));
  };
}

export function removeItem(id) {
  return function (dispatch, getState) {
    const lang = (getState().ui && getState().ui.language) || "ar";
    const cid = serverCustomerId(getState);
    let goneItemId = null;
    (getState().cart.rows || []).forEach(function (r) {
      if (r.id === Number(id) && r.itemId != null) goneItemId = r.itemId;
    });
    const product = ATYAB_byId(Number(id));
    dispatch(cartActions.removeRow(Number(id)));
    dispatch(uiActions.toastShown(removedMsg(product, lang)));
    if (cid) mirrorRemove(cid, goneItemId);
  };
}

export function clearTrolley() {
  return function (dispatch, getState) {
    const lang = (getState().ui && getState().ui.language) || "ar";
    const count = (getState().cart.rows || []).reduce(function (n, r) {
      return n + r.qty;
    }, 0);
    dispatch(cartActions.clearCart());
    const cid = serverCustomerId(getState);
    if (cid) {
      queueMirror(async function () {
        await clearServerBasket(cid);
      });
    }
    dispatch(
      uiActions.toastShown(
        lang === "en"
          ? count > 0
            ? "The cart was emptied"
            : "The cart is already empty"
          : count > 0
            ? "تم تفريغ العربة"
            : "العربة فارغة أصلاً"
      )
    );
  };
}

/* ---------- التحقق الموحّد من الكوبون (الخادم هو المرجع) ----------
   العقد: POST /api/coupons/{customerId}/validate ← { code }
     → 200 دائماً { valid:true, discountType, discountValue, discountAmount,
         freeShipping, subtotal, totalAfterDiscount, message }
     → 200 دائماً { valid:false, reason, minSubtotal?, currentSubtotal?,
         remaining?, message }
   ★ reason enum ثابت (NOT_FOUND·INACTIVE·EXPIRED·NOT_STARTED·MIN_SUBTOTAL·
     MIN_ITEMS·USAGE_LIMIT·USAGE_PER_CUSTOMER·EMPTY_BASKET) — الفرونت يعرض
     message الجاهزة ولا يفسّر نصاً أبداً، والرفض لا 4xx ولا يمنع الدفع.
   ★ الضيف بلا customerId: لا تحقق — رسالة دخول فقط ويُحفظ الكود ليُتحقق
     بعد الدخول. silent=true للتحقق الخلفي (تغيّرت العربة/قبل التأكيد). */
export function validateCouponCode(code, opts) {
  return async function (dispatch, getState) {
    const silent = !!(opts && opts.silent);
    const lang = (getState().ui && getState().ui.language) || "ar";
    const clean = String(code || "").trim().toUpperCase();
    function say(text, textEn) {
      dispatch(uiActions.toastShown(lang === "en" ? textEn || text : text));
    }
    function msgOf(text, textEn) {
      return lang === "en" ? textEn || text : text;
    }
    if (!clean) {
      if (!silent) {
        dispatch(cartActions.couponChecked({ valid: false, code: "", message: "اكتب كود الخصم أولاً.", messageEn: "Enter a discount code first." }));
        say("اكتب كود الخصم أولاً.", "Enter a discount code first.");
      }
      return null;
    }
    if (!isValidCouponFormat(clean)) {
      dispatch(cartActions.couponChecked({ valid: false, code: clean, reason: "NOT_FOUND", message: "صيغة الكود غير صحيحة.", messageEn: "Invalid code format." }));
      if (!silent) say("صيغة الكود غير صحيحة.", "Invalid code format.");
      return null;
    }
    const st = getState();
    const rows = st.cart.rows || [];
    if (!rows.length) {
      dispatch(cartActions.couponChecked({ valid: false, code: clean, reason: "EMPTY_BASKET", message: "العربة فارغة — أضف قطعة أولاً.", messageEn: "The cart is empty — add an item first." }));
      if (!silent) say("العربة فارغة — أضف قطعة أولاً.", "The cart is empty — add an item first.");
      return null;
    }
    /* ★ الضيف: الخادم يشترط customerId — نطلب الدخول بدل كذبة «غير صالح» */
    const cid = serverCustomerId(getState);
    if (!cid) {
      dispatch(cartActions.couponChecked({ keep: true, message: "سجّل الدخول أولاً ليُتحقق من الكوبون عند الدفع.", messageEn: "Log in first so the coupon can be verified at checkout." }));
      if (!silent) say("سجّل الدخول أولاً ليُتحقق من الكوبون عند الدفع.", "Log in first so the coupon can be verified at checkout.");
      return null;
    }
    const had = !!st.cart.coupon;
    let net = 0;
    rows.forEach(function (r) {
      const p = ATYAB_byId ? ATYAB_byId(Number(r.id)) : null;
      if (p) net += unitPriceOf(p) * (Number(r.qty) || 1);
    });
    dispatch(cartActions.couponCheckStarted());
    let d = null;
    try {
      const res = await authFetch(ENDPOINTS.couponValidate(cid), {
        method: "POST",
        body: { code: clean }
      });
      const text = await res.text().catch(function () { return ""; });
      try { d = text ? JSON.parse(text) : null; } catch (e) { d = null; }
      if (!res.ok || !d) throw new Error("bad-coupon-response");
    } catch (err) {
      dispatch(cartActions.couponCheckFailed());
      if (!silent) {
        dispatch(cartActions.couponChecked({ keep: true, message: "تعذّر التحقق من الكوبون — تحقق من الاتصال وحاول مجدداً.", messageEn: "Could not verify the coupon — check your connection and try again." }));
        say("تعذّر التحقق من الكوبون — تحقق من الاتصال وحاول مجدداً.", "Could not verify the coupon — check your connection and try again.");
      }
      return null;
    }
    if (d && d.valid) {
      const dtype = String(d.discountType || "percent").toLowerCase();
      dispatch(cartActions.couponChecked({
        valid: true,
        code: clean,
        discountType: dtype,
        discountValue: Number(d.discountValue) || 0,
        serverDiscount: d.discountAmount != null ? Number(d.discountAmount) : null,
        serverTotal: d.totalAfterDiscount != null ? Number(d.totalAfterDiscount) : null,
        freeShipping: !!d.freeShipping,
        snapshotNet: net,
        message: String(d.message || ("تم تطبيق الكوبون " + clean + ".")),
        messageEn: String(d.messageEn || d.message || ("Coupon applied: " + clean + "."))
      }));
      if (!silent) say("تم تطبيق الكوبون " + clean + ".", "Coupon applied: " + clean + ".");
      return d;
    }
    dispatch(cartActions.couponChecked({
      valid: false,
      code: clean,
      reason: String((d && d.reason) || "NOT_FOUND"),
      message: String((d && d.message) || ("الكود «" + clean + "» غير صالح.")),
      messageEn: String((d && (d.messageEn || d.message)) || ("The code «" + clean + "» is invalid."))
    }));
    /* ★ الصامت = صمت تام: التحقق الخلفي (تغيّرت العربة/قبل التأكيد)
       لا يُظهر أي تنبيه إطلاقاً — كان الشرط القديم (!silent || had)
       يُظهر رفض الكوبون تلقائياً لمن لديه كوبون محفوظ، فيرى الزائر
       عبارة لم يطلبها. أي تنبيه دخول/كوبون لا يظهر إلا بضغطة المستخدم. */
    if (!silent) say(msgOf((d && d.message) || ("الكود «" + clean + "» غير صالح."), (d && (d.messageEn || d.message)) || ("The code «" + clean + "» is invalid.")));
    return null;
  };
}

/* الاسم القديم يبقى كاسم مستعار للزرّ نفسه */
