/* ============================================================
   مزامنة السلة مع الخادم (للأعضاء فقط — الضيف محلي خالص)
   · السحب عند الدخول: اتحاد (الأعلى كمية) + دفع الناقص للخادم.
   · المرآة: كل عملية محلية ناجحة تُعكس للخادم في الخلفية.
   · الفشل الصامت: الشبكة عطلت؟ المحلي يبقى والسحب القادم يُقارب.
   ============================================================ */

export function serverCustomerId(getState) {
  try {
    const s = getState();
    return Number(s.user && s.user.auth && s.user.auth.customerId) || 0;
  } catch (e) {
    return 0;
  }
}

/* تسلسل عمليات الخادم — فلا يتسابق سحب مع مرآة على نفس السطر */
let basketChain = Promise.resolve();
function queueMirror(fn) {
  basketChain = basketChain.then(fn, fn);
}

/* ★ تصريف السلسلة: يُنتظَر قبل إنشاء الطلب (checkout/الدفع) حتى لا
   يتسابق PUT معلّق للمزامنة مع POST إنشاء الطلب. */
export function drainMirror() {
  return basketChain.then(function () {}, function () {});
}

async function readJsonSafe(res) {
  try {
    const t = await res.text();
    return t ? JSON.parse(t) : null;
  } catch (e) {
    return null;
  }
}

function basketItemsOf(payload) {
  if (!payload) return [];
  if (Array.isArray(payload)) return payload;
  const cands = [payload.items, payload.Items, payload.data, payload.basketItems];
  for (let i = 0; i < cands.length; i++) {
    if (Array.isArray(cands[i])) return cands[i];
  }
  return [];
}

function numOf(o, keys) {
  const r = o || {};
  for (let i = 0; i < keys.length; i++) {
    const v = r[keys[i]];
    if (v != null && v !== "" && !isNaN(Number(v))) return Number(v);
  }
  return null;
}

function findServerItemId(basket, productId) {
  const items = basketItemsOf(basket);
  for (let i = 0; i < items.length; i++) {
    if (numOf(items[i], ["productId", "ProductId"]) === Number(productId)) {
      return numOf(items[i], ["basketItemId", "itemId", "id", "Id"]);
    }
  }
  return null;
}

/* ---------- مسارات السلة برقم العميل دائماً (FRONTEND_CONTRACT §3) ----------
   ★ {customerId} في كل مسارات /api/baskets هو رقم العميل — وليس basketId.
   كل استدعاء يُرجع 200 + BasketDto (تُنشأ فارغة إن لم توجد).
   {itemId} وحده = basketItemId من الـGET — نلتقطه لكل صف (row.itemId)
   لنخاطب PUT/DELETE مباشرة. بلا كاش لمعرّفات ولا GET استكشافي. */

/* تفريغ سلة الخادم: DELETE /api/baskets/{customerId} */
export function clearServerBasket(cid) {
  cid = Number(cid) || 0;
  if (!cid) return Promise.resolve();
  return authFetch(ENDPOINTS.basketOf(cid), { method: "DELETE" }).then(
    function () {},
    function () {}
  );
}

/* هل الـ404 تعني «السلة/الحساب غير موجود»؟ (لا منتج غير موجود) */
function isBasketGone(payload) {
  if (!payload) return false;
  const s = [payload.detail, payload.message, payload.title, payload.error]
    .filter(Boolean)
    .map(function (v) {
      return String(v);
    })
    .join(" ");
  return /سلة|basket/i.test(s);
}

/* نصّ detail الخام من مغلف الخطأ — للعرض على الصف نفسه */
export function serverDetail(payload) {
  const d = payload || {};
  const s = d.detail != null ? String(d.detail) : d.message != null ? String(d.message) : d.error != null ? String(d.error) : "";
  return s.trim();
}

/* تحليل detail الـ409/404: المنتج (id أو اسم) والكمية المتاحة —
   { productId|null, productName|"", available|null }
   ★ الصيغة الحية: «الكمية المتاحة من مسك ابيض هي 0 فقط» — الاسم بين
   «من» و«هي/هو»، والعدد قبل «فقط» (الفجوة قد تطول بالأسماء). */
export function parseAvailability(detailText) {
  const t = String(detailText || "");
  if (!t) return null;
  function nearNum(re) {
    const m = t.match(re);
    return m ? Number(m[1]) : null;
  }
  /* ★ أول غير-null (لا ||): الصفر كمية شرعية («only 0 available») */
  function firstNum(list) {
    for (let i = 0; i < list.length; i++) {
      if (list[i] != null) return list[i];
    }
    return null;
  }
  const pid = firstNum([
    nearNum(/product\D{0,40}?(\d{3,})/i),
    nearNum(/منتج\D{0,40}?(\d{3,})/),
    nearNum(/ProductId"?\s*[:=]\s*"?(\d+)/i),
    nearNum(/"productId"\s*:\s*(\d+)/i)
  ]);
  let productName = "";
  let m = t.match(/من\s+(.+?)\s+(?:هي|هو)\s*\d+/);
  if (m && m[1]) productName = m[1].trim();
  if (!productName) {
    m = t.match(/\bof\s+(.+?)\s+is\s*\d+/i);
    if (m && m[1]) productName = m[1].trim();
  }
  const hasAvailWord = /متاح|متوفر|المخزون|available|stock|الكمية/i.test(t);
  let avail = null;
  if (hasAvailWord) {
    /* ★ «هي 0 فقط» / «only 2 available» — العدد قبل «فقط» أولاً */
    const mf = t.match(/(\d+)\s*فقط/);
    if (mf) avail = Number(mf[1]);
  }
  if (avail == null) {
    avail = firstNum([
      /* ★ الرقم قبل الكلمة أولاً («only 2 available») — قبل أن يلتقط
         «available ... 9000004» رقم المنتج خطأً */
      nearNum(/(\d+)\s*(?:المتاح|متوفر|المتوفر|available)/i),
      nearNum(/المتاح\D{0,40}?(\d+)/),
      nearNum(/متوفر\D{0,40}?(\d+)/),
      nearNum(/المتوفر\D{0,40}?(\d+)/),
      nearNum(/الكمية المتاحة\D{0,40}?(\d+)/),
      nearNum(/المخزون\D{0,40}?(\d+)/),
      nearNum(/available\D{0,10}?(\d+)/i),
      nearNum(/stock\D{0,10}?(\d+)/i)
    ]);
    /* ★ رقم بآلاف (معرّف منتج غالباً لا كمية)؟ لا نكذب — نرجع null */
    if (avail != null && avail > 9999) avail = null;
  }
  if (avail == null) return null;
  return { productId: pid, productName: productName, available: avail };
}

/* ★ الأفضل من استخراج النص: حقل رقمي صريح في الـpayload (إن وُجد) —
   والنص احتياط فقط. مرّر كائن الخطأ الكامل لا النص وحده. */
export function parseAvailabilityFromPayload(payload) {
  const d = payload || {};
  const cands = [d.availableQuantity, d.AvailableQuantity, d.available, d.Available, d.stockLeft, d.StockLeft];
  for (let i = 0; i < cands.length; i++) {
    const v = cands[i];
    if (v == null || v === "" || typeof v === "boolean") continue;
    const n = Number(v);
    if (isNaN(n)) continue;
    const text = parseAvailability(String(d.detail || d.message || d.error || ""));
    return {
      productId: text && text.productId,
      productName: (text && text.productName) || "",
      available: Math.max(0, Math.round(n))
    };
  }
  return parseAvailability(String(d.detail || d.message || d.error || ""));
}

/* سحب + دمج + دفع الناقص — تُستدعى عند كل دخول.
   ★ المسارات برقم العميل (§3)؛ الـGET تُنشئ سلة فارغة إن لم توجد،
   فـ404 تعني حساباً يتيماً (stale) لا «سلة بعد». بلا probe وهمي. */
export function pullBasket() {
  return function (dispatch, getState) {
    const cid = serverCustomerId(getState);
    if (!cid) return Promise.resolve();
    return new Promise(function (done) {
      queueMirror(async function () {
        try {
          const res = await authFetch(ENDPOINTS.basketOf(cid), { method: "GET" });
          if (res.status === 403 || res.status === 401) return done();
          if (!res.ok) {
            /* ★ 404 برسالة «سلة» = الحساب غير موجود عند الخادم (يتيم) —
               نوسم stale ليظهر بانر إعادة الدخول؛ غيرها = شبكة/خطأ عابر */
            if (res.status === 404) {
              let payload = null;
              try { payload = await readJsonSafe(res); } catch (e) {}
              if (isBasketGone(payload)) {
                atyabLog("basket STALE-ACCOUNT on pull", cid);
                dispatch(cartActions.basketStaleSet(true));
              }
            }
            /* ★ فشل ظاهر (لا stale ولا نجاح): بانر إعادة محاولة بدل الصمت */
            atyabLog("basket PULL-FAIL", cid, res.status);
            dispatch(cartActions.basketSyncSet(true));
            return done();
          }
          const basket = await readJsonSafe(res);
          dispatch(cartActions.basketStaleSet(false));
          dispatch(cartActions.basketSyncSet(false));
          const byId = {};
          const serverQty = {};
          basketItemsOf(basket).forEach(function (it) {
            const pid = numOf(it, ["productId", "ProductId"]);
            if (!pid) return;
            byId[pid] = {
              id: pid,
              qty: Math.max(1, Math.round(numOf(it, ["quantity", "qty", "Quantity"]) || 1)),
              itemId: numOf(it, ["basketItemId", "itemId", "id", "Id"])
            };
            serverQty[pid] = byId[pid].qty;
          });
          const local = (getState().cart.rows || []).slice();
          const missing = [];
          local.forEach(function (r) {
            const id = Number(r.id);
            if (!id) return;
            if (byId[id]) {
              byId[id].qty = Math.max(byId[id].qty, Math.round(Number(r.qty) || 1));
              if (byId[id].itemId == null && r.itemId != null) byId[id].itemId = Number(r.itemId);
            } else {
              byId[id] = { id: id, qty: Math.max(1, Math.round(Number(r.qty) || 1)), itemId: r.itemId != null ? Number(r.itemId) : undefined };
              if (byId[id].itemId == null) missing.push(byId[id]);
            }
          });
          for (let i = 0; i < missing.length; i++) {
            const r = missing[i];
            try {
              const pr = await authFetch(ENDPOINTS.basketAddItem(cid), {
                method: "POST",
                body: { productId: r.id, quantity: r.qty }
              });
              if (pr.status === 404) {
                const payload = await readJsonSafe(pr);
                if (isBasketGone(payload)) {
                  atyabLog("basket STALE-ACCOUNT", cid);
                  dispatch(cartActions.basketStaleSet(true));
                  return done();
                }
                /* ★ منتج مرفوض (غير موجود/غير نشط — §3): علّم الصف بنصّ
                   الخادم نفسه بدل الصمت، ليظهر على البطاقة */
                atyabLog("basket ADD-404", cid, r.id);
                dispatch(cartActions.basketRowNote({ id: r.id, note: serverDetail(payload) || "الخادم رفض هذا المنتج (غير موجود أو غير نشط)." }));
                continue;
              }
              if (pr.ok) {
                const payload = await readJsonSafe(pr);
                const found = findServerItemId(payload, r.id);
                if (found != null) r.itemId = found;
                dispatch(cartActions.basketRowNote({ id: r.id, note: null }));
              }
            } catch (e) {}
          }
          /* ★ دفع فروق الدمج للخادم: أي صف اندمج بكمية أعلى من كمية
             الخادم يُزامَن فوراً (PUT برقم السطر، وإلا POST) — قبل
             الاستبدال، ومباشرة هنا لا عبر pushRowQty (فهو يُصفَّر عبر
             السلسلة نفسها فيتعطّل انتظارُه من الداخل). */
          const diffs = [];
          Object.keys(byId).forEach(function (k) {
            const e = byId[k];
            e.max = maxQtyOf(e.id);
            if (serverQty[e.id] != null && e.qty !== serverQty[e.id]) diffs.push(e);
          });
          const diffFailed = [];
          for (let i = 0; i < diffs.length; i++) {
            const e = diffs[i];
            try {
              if (e.itemId != null) {
                const ur = await authFetch(ENDPOINTS.basketItemOne(cid, e.itemId), {
                  method: "PUT",
                  body: { quantity: e.qty }
                });
                if (!ur.ok) {
                  const payload = await readJsonSafe(ur);
                  diffFailed.push({ id: e.id, note: serverDetail(payload) || "تعذّرت مزامنة الكمية مع الخادم." });
                }
              } else {
                const pr = await authFetch(ENDPOINTS.basketAddItem(cid), {
                  method: "POST",
                  body: { productId: e.id, quantity: e.qty }
                });
                if (pr.ok) {
                  const found = findServerItemId(await readJsonSafe(pr), e.id);
                  if (found != null) e.itemId = found;
                } else {
                  const payload = await readJsonSafe(pr);
                  diffFailed.push({ id: e.id, note: serverDetail(payload) || "تعذّرت مزامنة الكمية مع الخادم." });
                }
              }
            } catch (err) {
              diffFailed.push({ id: e.id, note: "تعذّرت مزامنة الكمية — تحقق من الاتصال." });
            }
          }
          dispatch(cartActions.basketReplaced(Object.keys(byId).map(function (k) { return byId[k]; })));
          diffFailed.forEach(function (f) {
            dispatch(cartActions.basketRowNote({ id: f.id, note: f.note }));
          });
        } catch (e) {
          /* ★ انقطاع أثناء السحب: بانر إعادة محاولة بدل الصمت */
          atyabLog("basket PULL-ERROR", cid, String((e && e.message) || e));
          dispatch(cartActions.basketSyncSet(true));
        } finally {
          done();
        }
      });
    });
  };
}

/* عكس إضافة/تعديل كمية للخادم برقم العميل (§3) — يُقرأ الصف الطازج داخل السلسلة.
   ★ stale موسوم؟ لا POST جديد — السحب (pullBasket) هو طريق التعافي الوحيد. */
function mirrorUpsert(cid, dispatch, getState, id) {
  queueMirror(async function () {
    try {
      if (getState().cart && getState().cart.basketStale) return;
      const rows = getState().cart.rows || [];
      let row = null;
      rows.forEach(function (r) {
        if (Number(r.id) === Number(id)) row = r;
      });
      if (!row) return;
      /* ★ PUT بالـbasketItemId الملتقط (§3) — وإلا POST إضافة */
      if (row.itemId != null) {
        const res = await authFetch(ENDPOINTS.basketItemOne(cid, row.itemId), {
          method: "PUT",
          body: { quantity: Number(row.qty) || 1 }
        });
        if (res.ok) {
          dispatch(cartActions.basketRowNote({ id: row.id, note: null }));
          return;
        }
        if (res.status === 404) {
          const payload = await readJsonSafe(res);
          if (isBasketGone(payload)) {
            atyabLog("basket STALE-ACCOUNT on mirror", cid);
            dispatch(cartActions.basketStaleSet(true));
            return;
          }
          /* سطر ساقط والسلّة حيّة — أعد الإضافة */
        } else {
          return;
        }
      }
      const pr = await authFetch(ENDPOINTS.basketAddItem(cid), {
        method: "POST",
        body: { productId: row.id, quantity: Number(row.qty) || 1 }
      });
      if (pr.status === 404) {
        const payload = await readJsonSafe(pr);
        if (isBasketGone(payload)) {
          atyabLog("basket STALE-ACCOUNT on mirror", cid);
          dispatch(cartActions.basketStaleSet(true));
        } else {
          atyabLog("basket ADD-404", cid, row.id);
          dispatch(cartActions.basketRowNote({ id: row.id, note: serverDetail(payload) || "الخادم رفض هذا المنتج (غير موجود أو غير نشط)." }));
        }
        return;
      }
      if (pr.ok) {
        const payload = await readJsonSafe(pr);
        const found = findServerItemId(payload, row.id);
        if (found != null) dispatch(cartActions.basketItemLinked({ id: row.id, itemId: found }));
        else dispatch(cartActions.basketRowNote({ id: row.id, note: null }));
        dispatch(cartActions.basketStaleSet(false));
      }
    } catch (e) {}
  });
}

/* عكس حذف سطر للخادم — برقم العميل + basketItemId، وصمت تام عند stale */
function mirrorRemove(cid, itemId) {
  if (itemId == null) return;
  queueMirror(async function () {
    try {
      await authFetch(ENDPOINTS.basketItemOne(cid, itemId), { method: "DELETE" });
    } catch (e) {}
  });
}

/* دفع كمية صف واحد للخادم بعد تخفيض محلي (يستعملها تقليل الـ409) */
export function pushRowQty(productId) {
  return function (dispatch, getState) {
    const cid = serverCustomerId(getState);
    if (!cid) return Promise.resolve(false);
    return new Promise(function (done) {
      queueMirror(async function () {
        try {
          let row = null;
          (getState().cart.rows || []).forEach(function (r) {
            if (Number(r.id) === Number(productId)) row = r;
          });
          if (!row) return done(true);
          if (row.itemId != null) {
            const res = await authFetch(ENDPOINTS.basketItemOne(cid, row.itemId), {
              method: "PUT",
              body: { quantity: Number(row.qty) || 1 }
            });
            return done(res.ok);
          }
          const pr = await authFetch(ENDPOINTS.basketAddItem(cid), {
            method: "POST",
            body: { productId: row.id, quantity: Number(row.qty) || 1 }
          });
          if (pr.ok) {
            const found = findServerItemId(await readJsonSafe(pr), row.id);
            if (found != null) dispatch(cartActions.basketItemLinked({ id: row.id, itemId: found }));
          }
          return done(pr.ok);
        } catch (e) {
          return done(false);
        }
      });
    });
  };
}

/* إسقاط صف محلياً + حذف سطره في الخادم (المتاح صفر في الـ409) —
   ★ مع بانر «تمت الإزالة — انقر للحجز» (stockRemoved) */
export function dropRowEverywhere(productId) {
  return function (dispatch, getState) {
    let itemId = null;
    let pname = "";
    let pnameEn = "";
    (getState().cart.rows || []).forEach(function (r) {
      if (Number(r.id) === Number(productId)) {
        if (r.itemId != null) itemId = r.itemId;
        try {
          const p = ATYAB_byId ? ATYAB_byId(Number(productId)) : null;
          if (p) {
            pname = String(p.name || "");
            pnameEn = String(p.nameEn || p.name || "");
          }
        } catch (e) {}
      }
    });
    dispatch(cartActions.removeRow(Number(productId)));
    if (pname) dispatch(cartActions.stockRemoved({ name: pname, nameEn: pnameEn }));
    const cid = serverCustomerId(getState);
    if (!cid || itemId == null) return Promise.resolve();
    return new Promise(function (done) {
      queueMirror(async function () {
        try {
          await authFetch(ENDPOINTS.basketItemOne(cid, itemId), { method: "DELETE" });
        } catch (e) {} finally {
          done();
        }
      });
    });
  };
}
